export interface RegexDefinition {
    name: string;
    pattern: string;
    tags: string[];
}

export interface ValidationResult {
    inputTitle: string;
    regexName: string;
    status: 'Pass' | 'Fail';
    generatedTags: string[];
}

export function validateInput(input: string, regexDefinitions: RegexDefinition[]): ValidationResult[] {
    const results: ValidationResult[] = [];

    regexDefinitions.forEach(({ name, pattern, tags }) => {
        const regex = new RegExp(pattern);
        const isMatch = regex.test(input);

        results.push({
            inputTitle: input,
            regexName: name,
            status: isMatch ? 'Pass' : 'Fail',
            generatedTags: isMatch ? tags : []
        });
    });

    return results;
}
